from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class AuditScenario(BaseScenario):
    name = 'audit'
    description = 'Audit log tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='search_audit_log_basic', tool='search_audit_log', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'min_length': 1, 'all_items_keys': ['id', 'persona_name', 'operation_type']}, description='Search audit log returns fixture entries'), TestCase(name='search_audit_log_by_persona', tool='search_audit_log', params={'binder_id': 'binder_001', 'persona_name': 'Theorist'}, expected={'is_array': True, 'error': False, 'min_length': 1, 'all_items_field_equals': {'persona_name': 'Theorist'}}, description='Search audit log filtered by Theorist persona'), TestCase(name='search_audit_log_by_phase', tool='search_audit_log', params={'binder_id': 'binder_001', 'phase_number': 2}, expected={'is_array': True, 'error': False, 'min_length': 1, 'all_items_field_equals': {'phase_number': 2}}, description='Search audit log filtered by phase 2'), TestCase(name='search_audit_log_by_operation', tool='search_audit_log', params={'binder_id': 'binder_001', 'operation_type': 'store'}, expected={'is_array': True, 'error': False, 'min_length': 1, 'all_items_field_equals': {'operation_type': 'store'}}, description='Search audit log filtered by store operations'), TestCase(name='search_audit_log_limited', tool='search_audit_log', params={'binder_id': 'binder_001', 'limit': 5}, expected={'is_array': True, 'error': False, 'array_length_range': [1, 5]}, description='Search audit log with limit'), TestCase(name='get_artifact_audit_trail_existing', tool='get_artifact_audit_trail', params={'binder_id': 'binder_001', 'artifact_id': 'hyp_001'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get audit trail for artifact with entries'), TestCase(name='get_artifact_audit_trail_empty', tool='get_artifact_audit_trail', params={'binder_id': 'binder_001', 'artifact_id': 'nonexistent'}, expected={'is_array': True, 'error': False}, description='Get audit trail for non-existent artifact'), TestCase(name='get_audit_summary', tool='get_audit_summary', params={'binder_id': 'binder_001'}, expected={'json_valid': True, 'error': False}, description='Get audit summary statistics')]